package acesso.de.modificadores.estudando.domain;import java.util.Scanner;public class Pessoa {    private String name;    private int age;    private char sexo;    public void imprimir(){        System.out.println(this.name);        System.out.println(this.age);        System.out.println(this.sexo);    }    public void setName(String name, int age, char sexo){        this.name = name;        this.age = age;        this.sexo = sexo;    }}